        "endingTitle": "The Earth Shakes! Stassen Wins Outright!",
        "endingSubtitle": "",
        "endingText": "<p>No one expected this. God -- Harry Turtledove -- returns to take a look at the universe he created and faints. The impossible has happened, Harold Stassen -- the populist pied piper -- has won the election.\n\n<p>Only a few Republicans ride your coattails into Congress. The public may like you but they don’t like your party. You don’t care, you don’t need Congress -- you don’t need anyone but the public. Alben Barkley leads the congressional opposition to your presidency and you send out thousands of Executive Orders undermining him. The modern Imperial Presidency is born as you ignore the orders of Congress, doubling, then tripling the number of soldiers occupying the South. You force the Canadians to sign an armistice, then send Irving Morell’s tank column into Quebec -- reminding them who really rules the Quebecois. In everywhere but Congress you are met with success.\n\n<p>The Republicans won big in the midterms of ‘46, and Harold Stassen won a second term in a landslide victory. The Democrats were crushed between Harold’s insurgent party, and the resurgent Socialists. Harold Stassen retired from politics in ‘53 and spent the rest of his life rehabilitating the images of Lincoln and Blaine. By the time he passed away the American public loved Stassen just as much as it loved Blaine.",
