        "endingSubtitle": "",
        "endingText": "<p>Victory was never in the cards, but a deadlock is fertile ground for an ambitious man like you. Democrats and Socialists both come to you, begging and pleading with you to compromise with them, and give their man the presidency. Neither party is willing to entertain the idea of letting you ascend to the Powell House, unfortunately. Still, you cut a deal with Dewey’s Democrats, force yourself into Dewey’s cabinet, and force the traitor La Follette out of the Presidency.\n\n<p>The alliance between the Republicans and Democrats is tenuous, but it holds. In the ‘46 midterms you begin flexing your muscle in the coalition, and force the Democratic party to stop running candidates in districts you consider Republican strongholds. When Dewey ran for reelection in ‘48 the Republicans gained enough power that newspapers began referring to the newly born Republican-Democratic party. You rewrite Dewey’s limp-wristed Reconstruction plan into something with teeth, and by ‘50 Dixie culture is being suppressed across the nation. In ‘52 you ran for election on the Republican-Democratic ticket, promising to continue Reconstruction for a century more. \n\n<p>Harold Stassen won the 1952 election in a landslide. The ‘56 race was closer, but the results were never truly in doubt. Republicans across the country slowly push the Democrats out of the coalition, and a new party system is born. Schools across the country teach of the three greatest Presidents of the Union, Abraham Lincoln, James Blaine, and Harold Stassen. Could you have ever hoped for anything more?",
